import json

with open('/tmp/chart_data.json') as f:
    data = json.load(f)

# Serialize slices we need inline
weekly_json = json.dumps(data['weekly'])
sub_weekly_json = json.dumps(data['sub_weekly'])
reg_yearly_json = json.dumps(data['reg_yearly'])
inc_yearly_json = json.dumps(data['inc_yearly'])
country_avg_json = json.dumps(data['country_avg'])
tax_income_json = json.dumps(data['tax_income'])

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Fuel Price Trends &amp; Policy Impact Analysis (2020–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
<style>
  :root {{
    --navy: #0d1b2a;
    --blue: #1b4f72;
    --accent: #2e86ab;
    --gold: #e8b600;
    --light: #f0f4f8;
    --muted: #6b7a8d;
    --green: #27ae60;
    --red: #c0392b;
    --orange: #e67e22;
    --purple: #8e44ad;
    --teal: #16a085;
    --pink: #c0392b;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ font-family: 'Segoe UI', Arial, sans-serif; background: #f5f7fa; color: #1a2332; line-height: 1.6; }}

  /* Cover */
  .cover {{
    background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 60%, var(--accent) 100%);
    color: white;
    padding: 60px 48px 48px;
    position: relative;
    overflow: hidden;
  }}
  .cover::before {{
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 400px; height: 400px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }}
  .cover-tag {{ font-size: 11px; font-weight: 700; letter-spacing: 3px; text-transform: uppercase; color: var(--gold); margin-bottom: 20px; }}
  .cover h1 {{ font-size: 36px; font-weight: 800; line-height: 1.2; max-width: 700px; margin-bottom: 16px; }}
  .cover .subtitle {{ font-size: 16px; color: rgba(255,255,255,0.8); max-width: 620px; margin-bottom: 36px; }}
  .cover-meta {{ display: flex; gap: 40px; font-size: 13px; color: rgba(255,255,255,0.65); }}
  .cover-meta span strong {{ color: rgba(255,255,255,0.9); display: block; font-size: 14px; }}

  /* KPI strip */
  .kpi-strip {{
    background: white;
    display: flex;
    gap: 0;
    border-bottom: 3px solid var(--accent);
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  }}
  .kpi-card {{
    flex: 1;
    padding: 22px 20px;
    border-right: 1px solid #e8ecf0;
    text-align: center;
  }}
  .kpi-card:last-child {{ border-right: none; }}
  .kpi-value {{ font-size: 28px; font-weight: 800; color: var(--accent); line-height: 1; }}
  .kpi-label {{ font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; margin-top: 6px; }}
  .kpi-sub {{ font-size: 12px; color: var(--muted); margin-top: 3px; }}

  /* Layout */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}
  .section {{ padding: 48px 0 32px; }}
  .section-header {{
    display: flex; align-items: baseline; gap: 16px;
    border-bottom: 2px solid var(--accent);
    padding-bottom: 12px;
    margin-bottom: 28px;
  }}
  .section-number {{ font-size: 13px; font-weight: 700; color: var(--accent); letter-spacing: 1px; text-transform: uppercase; }}
  .section-title {{ font-size: 24px; font-weight: 700; color: var(--navy); }}
  .section-desc {{ font-size: 14px; color: var(--muted); margin-bottom: 24px; max-width: 800px; }}

  /* Charts */
  .chart-grid {{ display: grid; gap: 24px; }}
  .chart-grid.two {{ grid-template-columns: 1fr 1fr; }}
  .chart-grid.three {{ grid-template-columns: 1fr 1fr 1fr; }}
  .chart-box {{
    background: white;
    border-radius: 10px;
    padding: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    border: 1px solid #e8ecf0;
  }}
  .chart-box.full {{ grid-column: 1 / -1; }}
  .chart-title {{ font-size: 14px; font-weight: 700; color: var(--navy); margin-bottom: 4px; }}
  .chart-subtitle {{ font-size: 12px; color: var(--muted); margin-bottom: 18px; }}
  .chart-wrap {{ position: relative; }}

  /* Callout boxes */
  .callout-grid {{ display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; margin-bottom: 24px; }}
  .callout {{
    background: white;
    border-radius: 8px;
    padding: 18px 20px;
    border-left: 4px solid var(--accent);
    box-shadow: 0 1px 6px rgba(0,0,0,0.05);
  }}
  .callout.gold {{ border-left-color: var(--gold); }}
  .callout.green {{ border-left-color: var(--green); }}
  .callout.red {{ border-left-color: var(--red); }}
  .callout.purple {{ border-left-color: var(--purple); }}
  .callout.orange {{ border-left-color: var(--orange); }}
  .callout-label {{ font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px; color: var(--muted); margin-bottom: 6px; }}
  .callout-value {{ font-size: 22px; font-weight: 800; color: var(--navy); line-height: 1; }}
  .callout-desc {{ font-size: 12px; color: var(--muted); margin-top: 5px; }}

  /* Tables */
  .table-wrap {{ overflow-x: auto; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  th {{ background: var(--navy); color: white; font-weight: 600; padding: 10px 12px; text-align: left; font-size: 12px; letter-spacing: 0.3px; }}
  td {{ padding: 9px 12px; border-bottom: 1px solid #edf0f3; }}
  tr:hover td {{ background: #f7f9fc; }}
  .badge {{
    display: inline-block; padding: 2px 8px; border-radius: 12px;
    font-size: 11px; font-weight: 700; letter-spacing: 0.3px;
  }}
  .badge-low {{ background: #fdecea; color: var(--red); }}
  .badge-high {{ background: #e8f5e9; color: var(--green); }}
  .badge-medium {{ background: #fff3e0; color: var(--orange); }}
  .badge-vh {{ background: #ede7f6; color: var(--purple); }}

  /* Findings */
  .findings-list {{ display: flex; flex-direction: column; gap: 16px; }}
  .finding {{
    background: white;
    border-radius: 10px;
    padding: 22px 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    border: 1px solid #e8ecf0;
    display: grid;
    grid-template-columns: 48px 1fr;
    gap: 16px;
    align-items: start;
  }}
  .finding-num {{
    width: 48px; height: 48px;
    background: var(--navy);
    color: var(--gold);
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 18px; font-weight: 800;
    flex-shrink: 0;
  }}
  .finding-body h4 {{ font-size: 15px; font-weight: 700; color: var(--navy); margin-bottom: 6px; }}
  .finding-body p {{ font-size: 13px; color: #4a5568; line-height: 1.6; }}
  .finding-tag {{
    display: inline-block; padding: 2px 10px; border-radius: 12px;
    font-size: 10px; font-weight: 700; letter-spacing: 0.8px;
    text-transform: uppercase; margin-bottom: 8px;
  }}
  .tag-finding {{ background: #e3f2fd; color: #1565c0; }}
  .tag-policy {{ background: #f3e5f5; color: #6a1b9a; }}
  .tag-risk {{ background: #fff8e1; color: #e65100; }}

  /* Annotation band */
  .annotation-band {{
    background: linear-gradient(to right, #1b4f72, var(--accent));
    color: white;
    padding: 16px 24px;
    border-radius: 8px;
    margin-bottom: 24px;
    font-size: 13px;
    display: flex; gap: 12px; align-items: center;
  }}
  .annotation-band strong {{ color: var(--gold); }}

  /* Footer */
  footer {{
    background: var(--navy);
    color: rgba(255,255,255,0.5);
    padding: 24px 48px;
    font-size: 12px;
    display: flex; justify-content: space-between;
    margin-top: 48px;
  }}

  /* Nav */
  .toc {{
    background: white;
    border-bottom: 1px solid #e8ecf0;
    padding: 0 48px;
    position: sticky; top: 0;
    z-index: 100;
    box-shadow: 0 1px 4px rgba(0,0,0,0.08);
  }}
  .toc-inner {{ display: flex; gap: 0; overflow-x: auto; }}
  .toc-item {{
    padding: 14px 18px;
    font-size: 12px; font-weight: 600;
    color: var(--muted);
    text-decoration: none;
    white-space: nowrap;
    border-bottom: 3px solid transparent;
    transition: all 0.15s;
  }}
  .toc-item:hover {{ color: var(--accent); border-bottom-color: var(--accent); }}

  @media(max-width: 900px) {{
    .chart-grid.two, .chart-grid.three {{ grid-template-columns: 1fr; }}
    .callout-grid {{ grid-template-columns: 1fr 1fr; }}
    .kpi-strip {{ flex-wrap: wrap; }}
    .kpi-card {{ min-width: 150px; }}
  }}
</style>
</head>
<body>

<!-- COVER -->
<div class="cover">
  <div class="cover-tag">Energy Policy Analysis</div>
  <h1>Global Fuel Price Trends &amp; Policy Impact Analysis</h1>
  <div class="subtitle">A comprehensive trend analysis of retail fuel prices across 84 countries — examining how Brent Crude benchmarks, taxation, and subsidy regimes have shaped consumer costs from January 2020 through April 2026.</div>
  <div class="cover-meta">
    <span><strong>Period Covered</strong>Jan 2020 – Apr 2026</span>
    <span><strong>Countries</strong>84 Sovereign States</span>
    <span><strong>Data Points</strong>27,468 Weekly Records</span>
    <span><strong>Audience</strong>Energy Policy Analysts</span>
    <span><strong>Published</strong>April 2026</span>
  </div>
</div>

<!-- TOC NAV -->
<nav class="toc">
  <div class="toc-inner">
    <a class="toc-item" href="#overview">1. Global Overview</a>
    <a class="toc-item" href="#temporal">2. Temporal Trends &amp; Volatility</a>
    <a class="toc-item" href="#regional">3. Regional Disparities</a>
    <a class="toc-item" href="#subsidy">4. Subsidies &amp; Taxation</a>
    <a class="toc-item" href="#income">5. Income-Level Affordability</a>
    <a class="toc-item" href="#findings">6. Key Findings &amp; Policy Implications</a>
  </div>
</nav>

<!-- KPI STRIP -->
<div class="kpi-strip">
  <div class="kpi-card">
    <div class="kpi-value">$2.28</div>
    <div class="kpi-label">Avg Global Petrol</div>
    <div class="kpi-sub">USD/Liter, 2020–2026</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">0.996</div>
    <div class="kpi-label">Brent–Retail Correlation</div>
    <div class="kpi-sub">Petrol % change vs Brent % change</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">79.5%</div>
    <div class="kpi-label">Subsidy Dampening</div>
    <div class="kpi-sub">High vs Low subsidy countries</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">$2.87</div>
    <div class="kpi-label">Regional Price Spread</div>
    <div class="kpi-sub">Max–Min regional avg, 2026</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">34.7%</div>
    <div class="kpi-label">Avg Tax (High-Income)</div>
    <div class="kpi-sub">vs 21.1% in Middle-Income nations</div>
  </div>
</div>

<!-- SECTION 1: GLOBAL OVERVIEW -->
<div id="overview" class="container">
  <div class="section">
    <div class="section-header">
      <span class="section-number">Section 01</span>
      <span class="section-title">Global Fuel Price Overview</span>
    </div>
    <p class="section-desc">Summary statistics for petrol, diesel, and LPG across 84 countries and 327 weekly observations (Jan 2020 – Apr 2026). Brent Crude serves as the global commodity baseline from which retail deviations are measured.</p>

    <div class="callout-grid">
      <div class="callout">
        <div class="callout-label">Petrol — Global Avg</div>
        <div class="callout-value">$2.282/L</div>
        <div class="callout-desc">Mean across all countries and weeks. Range: $0.016 (Venezuela) to $5.54 (Hong Kong).</div>
      </div>
      <div class="callout gold">
        <div class="callout-label">Diesel — Global Avg</div>
        <div class="callout-value">$2.134/L</div>
        <div class="callout-desc">Diesel consistently trades at a modest discount to petrol across all regions and years.</div>
      </div>
      <div class="callout green">
        <div class="callout-label">LPG — Global Avg</div>
        <div class="callout-value">$1.712/L</div>
        <div class="callout-desc">LPG remains the most affordable fuel type globally — 25% below petrol on average.</div>
      </div>
      <div class="callout red">
        <div class="callout-label">Brent Crude — Period Low</div>
        <div class="callout-value">$47.97/bbl</div>
        <div class="callout-desc">COVID-19 demand collapse trough, April 2020. Lowest level in the 6-year window.</div>
      </div>
      <div class="callout purple">
        <div class="callout-label">Brent Crude — Period High</div>
        <div class="callout-value">$130.00/bbl</div>
        <div class="callout-desc">Peak during the 2022 energy crisis, driven by geopolitical supply disruptions.</div>
      </div>
      <div class="callout orange">
        <div class="callout-label">Brent Crude — 2026 Avg</div>
        <div class="callout-value">$123.75/bbl</div>
        <div class="callout-desc">Crude remained elevated through early 2026, sustaining upward pressure on retail prices.</div>
      </div>
    </div>

    <div class="chart-grid two">
      <div class="chart-box">
        <div class="chart-title">Average Retail Price by Fuel Type (USD/Liter)</div>
        <div class="chart-subtitle">Annual averages, 2020–2026. All three fuel types track Brent closely.</div>
        <div class="chart-wrap"><canvas id="fuelTypeYearly" height="220"></canvas></div>
      </div>
      <div class="chart-box">
        <div class="chart-title">Country Price Distribution — Petrol (USD/Liter)</div>
        <div class="chart-subtitle">Period-average petrol prices, 84 countries ranked from lowest to highest.</div>
        <div class="chart-wrap"><canvas id="countryDistribution" height="220"></canvas></div>
      </div>
    </div>

    <div class="chart-box" style="margin-top:24px">
      <div class="chart-title">Top 10 Highest &amp; Lowest Average Petrol Prices by Country</div>
      <div class="chart-subtitle">Period-average 2020–2026. Subsidy regime drives most of the range.</div>
      <div class="table-wrap">
        <table id="countryRankTable"></table>
      </div>
    </div>
  </div>
</div>

<!-- SECTION 2: TEMPORAL TRENDS -->
<div id="temporal" style="background: #f5f7fa; padding: 0 0 8px;">
<div class="container">
  <div class="section">
    <div class="section-header">
      <span class="section-number">Section 02</span>
      <span class="section-title">Temporal Price Trends &amp; Volatility</span>
    </div>
    <p class="section-desc">Weekly price dynamics from Jan 2020 to Apr 2026. Key episodes: COVID-19 demand collapse (Feb–Apr 2020), post-pandemic surge (2021), 2022 energy crisis peak, and sustained high-price environment (2023–2026).</p>

    <div class="annotation-band">
      &#9432;&nbsp; <strong>Brent–Retail Correlation:</strong> Weekly % change in Brent Crude explains <strong>99.6%</strong> of global average retail petrol price variance (r = 0.996). For low-subsidy countries the correlation is near-perfect; high-subsidy countries show meaningfully lower pass-through (r = 0.741).
    </div>

    <div class="chart-box full" style="margin-bottom:24px">
      <div class="chart-title">Weekly Global Averages: Brent Crude vs. Retail Fuel Prices (2020–2026)</div>
      <div class="chart-subtitle">Brent in USD/bbl (right axis). Retail prices in USD/Liter (left axis). Gray bands mark key policy events.</div>
      <div class="chart-wrap"><canvas id="weeklyTimeSeries" height="160"></canvas></div>
    </div>

    <div class="chart-grid two">
      <div class="chart-box">
        <div class="chart-title">Annual Average Brent Crude Price (USD/bbl)</div>
        <div class="chart-subtitle">Year-over-year trajectory showing 2020 trough, 2022 peak, and sustained elevation.</div>
        <div class="chart-wrap"><canvas id="brentYearly" height="220"></canvas></div>
      </div>
      <div class="chart-box">
        <div class="chart-title">Price Volatility by Subsidy Level (Std Dev, USD/Liter)</div>
        <div class="chart-subtitle">Low-subsidy countries absorb 4.8× more price variance than High-subsidy nations.</div>
        <div class="chart-wrap"><canvas id="volatilityBar" height="220"></canvas></div>
      </div>
    </div>
  </div>
